cd /tmp && cat > /tmp/bot-check.mjs <<'EOF'
import assert from "node:assert/strict";
import { decideWhatsApp as d } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-inv-g5-3/bot.mjs";

const T0 = "1767272400";                       // 2026-01-01T13:00:00Z
const at = (s) => new Date(Date.parse("2026-01-01T13:00:00Z") + s * 1000);
const H = 3600;
const c = (over = {}) => ({ optedIn: true, lastInboundTimestamp: T0, ...over });

// opt-in gate, every type
assert.deepEqual(d({ type: "template", contact: c({ optedIn: false }) }, at(0)), { allowed: false, reason: "not_opted_in" });
assert.deepEqual(d({ type: "text", contact: c({ optedIn: false }) }, at(0)), { allowed: false, reason: "not_opted_in" });
assert.deepEqual(d({ type: "text", contact: { lastInboundTimestamp: T0 } }, at(0)), { allowed: false, reason: "not_opted_in" });
assert.deepEqual(d({ type: "template", contact: { optedIn: "true" } }, at(0)), { allowed: false, reason: "not_opted_in" });

// templates: allowed any time once opted in (no inbound, stale inbound)
assert.deepEqual(d({ type: "template", contact: c({ lastInboundTimestamp: null }) }, at(0)), { allowed: true, reason: null });
assert.deepEqual(d({ type: "template", contact: c() }, at(100 * H)), { allowed: true, reason: null });

// text inside window
assert.deepEqual(d({ type: "text", contact: c() }, at(0)), { allowed: true, reason: null });
assert.deepEqual(d({ type: "text", contact: c() }, at(24 * H - 1)), { allowed: true, reason: null });

// text at/after 24h boundary
assert.deepEqual(d({ type: "text", contact: c() }, at(24 * H)), { allowed: false, reason: "service_window_closed" });
assert.deepEqual(d({ type: "text", contact: c() }, at(30 * H)), { allowed: false, reason: "service_window_closed" });

// text with no inbound ever
assert.deepEqual(d({ type: "text", contact: c({ lastInboundTimestamp: null }) }, at(0)), { allowed: false, reason: "service_window_closed" });
assert.deepEqual(d({ type: "text", contact: c({ lastInboundTimestamp: undefined }) }, at(0)), { allowed: false, reason: "service_window_closed" });

// malformed / future timestamps fail closed
for (const bad of ["", "abc", "1767272400.5", " 1767272400", 1767272400, "-5", "99999999999999999999999"]) {
  assert.deepEqual(d({ type: "text", contact: c({ lastInboundTimestamp: bad }) }, at(0)), { allowed: false, reason: "invalid_last_inbound_timestamp" }, String(bad));
}
assert.deepEqual(d({ type: "text", contact: c() }, at(-1)), { allowed: false, reason: "invalid_last_inbound_timestamp" });

// unknown type
assert.deepEqual(d({ type: "image", contact: c() }, at(0)), { allowed: false, reason: "unsupported_message_type" });

// bad now
assert.throws(() => d({ type: "template", contact: c() }, new Date("x")), TypeError);
assert.throws(() => d({ type: "template", contact: c() }, "2026-01-01"), TypeError);

// reason codes distinct per rule
const codes = new Set(["not_opted_in", "unsupported_message_type", "service_window_closed", "invalid_last_inbound_timestamp"]);
assert.equal(codes.size, 4);
console.log("all checks passed");
EOF
